import java.util.*;

public class Main {
    int maximumRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        int n = chargeTimes.length;
        int best = 0;
        for (int i = 0; i < n; i++) {
            int maxCharge = 0;
            long sumRunning = 0;
            for (int j = i; j < n; j++) {                                            // extend the window one robot at a time
                maxCharge = Math.max(maxCharge, chargeTimes[j]);
                sumRunning += runningCosts[j];
                int k = j - i + 1;
                long cost = maxCharge + (long) k * sumRunning;
                if (cost <= budget) {
                    best = Math.max(best, k);
                } else {
                    break;                                                              // further extension only makes k (and thus cost) larger
                }
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] chargeTimes = {3, 6, 1, 3, 4};
        int[] runningCosts = {2, 1, 3, 4, 5};
        System.out.println(solution.maximumRobots(chargeTimes, runningCosts, 25));
    }
}

