import java.util.*;

public class Main {
    int maximumRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        Deque<Integer> maxDeque = new ArrayDeque<>();                                // DECREASING deque of indices: front is always the window's max charge time
        int left = 0;
        long sumRunning = 0;
        int best = 0;
        for (int right = 0; right < chargeTimes.length; right++) {
            while (!maxDeque.isEmpty() && chargeTimes[maxDeque.peekLast()] <= chargeTimes[right]) {
                maxDeque.pollLast();                                                    // maintain decreasing order
            }
            maxDeque.addLast(right);
            sumRunning += runningCosts[right];

            int k = right - left + 1;
            while (!maxDeque.isEmpty() && chargeTimes[maxDeque.peekFirst()] + (long) k * sumRunning > budget) {
                if (maxDeque.peekFirst() == left) maxDeque.pollFirst();                    // the window's current max leaves as we shrink
                sumRunning -= runningCosts[left];
                left++;
                k = right - left + 1;
            }

            best = Math.max(best, k);
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] chargeTimes = {3, 6, 1, 3, 4};
        int[] runningCosts = {2, 1, 3, 4, 5};
        System.out.println(solution.maximumRobots(chargeTimes, runningCosts, 25));
    }
}

