#include <bits/stdc++.h>
using namespace std;

int maximumRobots(vector<int>& chargeTimes, vector<int>& runningCosts, long long budget) {
    deque<int> maxDeque;                                                                // DECREASING deque of indices: front is always the window's max charge time
    int left = 0;
    long long sumRunning = 0;
    int best = 0;
    for (int right = 0; right < (int)chargeTimes.size(); right++) {
        while (!maxDeque.empty() && chargeTimes[maxDeque.back()] <= chargeTimes[right]) {
            maxDeque.pop_back();                                                            // maintain decreasing order
        }
        maxDeque.push_back(right);
        sumRunning += runningCosts[right];

        int k = right - left + 1;
        while (!maxDeque.empty() && chargeTimes[maxDeque.front()] + (long long)k * sumRunning > budget) {
            if (maxDeque.front() == left) maxDeque.pop_front();                                // the window's current max leaves as we shrink
            sumRunning -= runningCosts[left];
            left++;
            k = right - left + 1;
        }

        best = max(best, k);
    }
    return best;
}

int main() {
    vector<int> chargeTimes = {3, 6, 1, 3, 4};
    vector<int> runningCosts = {2, 1, 3, 4, 5};
    cout << maximumRobots(chargeTimes, runningCosts, 25) << endl;
    return 0;
}
